html:
{%- set currency = doc.currency -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=currency) }}{%- endmacro -%}
{%- set earnings = doc.earnings | selectattr("statistical_component", "ne", 1) | list -%}
{%- set deductions = doc.deductions | selectattr("statistical_component", "ne", 1) | list -%}
<style>
	.bk-slip { font-family: Geist, "Helvetica Neue", Arial, sans-serif; color: #0e1433; font-size: 12.5px; }
	.bk-top { display: flex; justify-content: space-between; align-items: flex-end; border-bottom: 3px solid #c9f24b; padding-bottom: 10px; margin-bottom: 18px; }
	.bk-kicker { font-size: 10.5px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #5a6384; }
	.bk-title { font-size: 26px; font-weight: 800; letter-spacing: -0.01em; margin: 2px 0 0; }
	.bk-muted { color: #5a6384; }
	.bk-grid { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
	.bk-grid td { padding: 3px 0; vertical-align: top; border: 0 !important; }
	.bk-grid .bk-label { width: 22%; color: #5a6384; font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; font-weight: 600; }
	.bk-cols { width: 100%; border-collapse: separate; border-spacing: 0; }
	.bk-cols > tbody > tr > td { width: 50%; vertical-align: top; padding: 0 !important; border: 0 !important; }
	.bk-cols > tbody > tr > td:first-child { padding-right: 10px !important; }
	.bk-cols > tbody > tr > td:last-child { padding-left: 10px !important; }
	.bk-table { width: 100%; border-collapse: collapse; }
	.bk-table th { background: #f2f4f9 !important; color: #394264; text-align: left; font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.05em; padding: 7px 10px !important; border: 0 !important; }
	.bk-table td { padding: 6px 10px !important; border: 0 !important; border-bottom: 1px solid #e5e9f2 !important; }
	.bk-table .bk-r { text-align: right; white-space: nowrap; }
	.bk-table tfoot td { font-weight: 700; border-bottom: 0 !important; border-top: 2px solid #d5dbe8 !important; }
	.bk-net { margin-top: 18px; background: #0e1433 !important; color: #fff; border-radius: 10px; padding: 14px 18px; display: flex; justify-content: space-between; align-items: center; }
	.bk-net .bk-kicker { color: #9aa3c7; }
	.bk-net-amount { font-size: 24px; font-weight: 800; color: #c9f24b; }
	.bk-words { margin-top: 6px; font-size: 11.5px; }
	.bk-section { margin-top: 20px; font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: #2b3fe0; margin-bottom: 6px; }
</style>
<div class="bk-slip">
	<div class="bk-top">
		<div>
			<div class="bk-kicker">{{ _("Payslip") }}{% if doc.docstatus == 0 %} · {{ _("Draft") }}{% elif doc.docstatus == 2 %} · {{ _("Cancelled") }}{% endif %}</div>
			<h2 class="bk-title">{{ frappe.utils.formatdate(doc.start_date, "MMMM yyyy") if doc.payroll_frequency == "Monthly" else frappe.utils.formatdate(doc.start_date) ~ " – " ~ frappe.utils.formatdate(doc.end_date) }}</h2>
		</div>
		<div style="text-align: right">
			<div style="font-weight: 700; font-size: 14px">{{ doc.company }}</div>
			<div class="bk-muted">{{ doc.name }}</div>
		</div>
	</div>

	<table class="bk-grid">
		<tr>
			<td class="bk-label">{{ _("Employee") }}</td>
			<td><b>{{ doc.employee_name }}</b> <span class="bk-muted">· {{ doc.employee }}</span></td>
			<td class="bk-label">{{ _("Period") }}</td>
			<td>{{ frappe.utils.formatdate(doc.start_date) }} – {{ frappe.utils.formatdate(doc.end_date) }}</td>
		</tr>
		<tr>
			<td class="bk-label">{{ _("Role") }}</td>
			<td>{{ [doc.designation, doc.department] | select | join(" · ") or "—" }}</td>
			<td class="bk-label">{{ _("Paid days") }}</td>
			<td>
				{{ "%g" | format(frappe.utils.flt(doc.payment_days, 2)) }} {{ _("of") }} {{ "%g" | format(frappe.utils.flt(doc.total_working_days, 2)) }}
				{% if doc.leave_without_pay %}<span class="bk-muted"> · {{ "%g" | format(doc.leave_without_pay) }} {{ _("unpaid leave") }}</span>{% endif %}
				{% if doc.absent_days %}<span class="bk-muted"> · {{ "%g" | format(doc.absent_days) }} {{ _("absent") }}</span>{% endif %}
			</td>
		</tr>
		{% if doc.bank_name or doc.bank_account_no or doc.mode_of_payment %}
		<tr>
			<td class="bk-label">{{ _("Paid to") }}</td>
			<td>{{ [doc.bank_name, doc.bank_account_no] | select | join(" · ") or doc.mode_of_payment }}</td>
			<td class="bk-label">{% if doc.salary_slip_based_on_timesheet %}{{ _("Hours") }}{% endif %}</td>
			<td>{% if doc.salary_slip_based_on_timesheet %}{{ doc.total_working_hours }} × {{ money(doc.hour_rate) }}{% endif %}</td>
		</tr>
		{% endif %}
	</table>

	<table class="bk-cols">
		<tr>
			<td>
				<table class="bk-table">
					<thead><tr><th>{{ _("Earnings") }}</th><th class="bk-r">{{ _("Amount") }}</th></tr></thead>
					<tbody>
						{% for d in earnings %}
						<tr><td>{{ d.salary_component }}</td><td class="bk-r">{{ money(d.amount) }}</td></tr>
						{% else %}
						<tr><td colspan="2" class="bk-muted">—</td></tr>
						{% endfor %}
					</tbody>
					<tfoot><tr><td>{{ _("Gross pay") }}</td><td class="bk-r">{{ money(doc.gross_pay) }}</td></tr></tfoot>
				</table>
			</td>
			<td>
				<table class="bk-table">
					<thead><tr><th>{{ _("Deductions") }}</th><th class="bk-r">{{ _("Amount") }}</th></tr></thead>
					<tbody>
						{% for d in deductions %}
						<tr><td>{{ d.salary_component }}</td><td class="bk-r">{{ money(d.amount) }}</td></tr>
						{% else %}
						<tr><td colspan="2" class="bk-muted">—</td></tr>
						{% endfor %}
					</tbody>
					<tfoot><tr><td>{{ _("Total deductions") }}</td><td class="bk-r">{{ money(doc.total_deduction) }}</td></tr></tfoot>
				</table>
			</td>
		</tr>
	</table>

	<div class="bk-net">
		<div>
			<div class="bk-kicker">{{ _("Net pay") }}</div>
			{% if doc.total_in_words %}<div class="bk-words">{{ doc.total_in_words }}</div>{% endif %}
		</div>
		<div class="bk-net-amount">{{ money(doc.rounded_total or doc.net_pay) }}</div>
	</div>

	{% if doc.leave_details %}
	<div class="bk-section">{{ _("Leave") }}</div>
	<table class="bk-table">
		<thead>
			<tr>
				<th>{{ _("Leave type") }}</th>
				<th class="bk-r">{{ _("Allocated") }}</th>
				<th class="bk-r">{{ _("Used") }}</th>
				<th class="bk-r">{{ _("Pending approval") }}</th>
				<th class="bk-r">{{ _("Available") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for l in doc.leave_details %}
			<tr>
				<td>{{ l.leave_type }}</td>
				<td class="bk-r">{{ l.total_allocated_leaves }}</td>
				<td class="bk-r">{{ l.used_leaves }}</td>
				<td class="bk-r">{{ l.pending_leaves }}</td>
				<td class="bk-r"><b>{{ l.available_leaves }}</b></td>
			</tr>
			{% endfor %}
		</tbody>
	</table>
	{% endif %}
</div>
